use crate::{scene::Scene,scene_document,instance_specimen,archive::Bundle};
use session_rust::{proto,Xform};
use prost::Message;
use std::rc::Rc;

#[test]
fn original_instances_share_geometry_apply_session_placement_once_and_roundtrip_references() {
    let source=instance_specimen::message();let original=source.definitions.as_ref().unwrap().meshes[0].clone();let mut scene=Scene::empty();scene_document::import(&mut scene,&source.encode_to_vec(),"",&Xform::translation(0.25,0.,0.),0.).unwrap();let a=&scene.objects()[0];let b=&scene.objects()[1];assert!(Rc::ptr_eq(&a.mesh,&b.mesh));assert!(Rc::ptr_eq(a.geometry().unwrap(),b.geometry().unwrap()));assert_ne!(a.id,b.id);assert_ne!(a.guid,b.guid);assert_eq!(a.model.m[12],1_000_000_000.125-1.+1000.+0.25);assert_eq!(b.model.m[12],1_000_000_000.125+1.+0.25);assert!(scene.pick_id(a.id.value()).is_some());assert!(scene.pick_id(b.id.value()).is_none());assert_eq!(a.geometry().unwrap().to_proto(),original);assert!(scene.instances[&a.id].instance.xform.is_identity());
    let saved=Bundle::decode(&crate::scene_archive::save(&scene).unwrap()).unwrap();let document=proto::Session::decode(saved.documents[0].as_slice()).unwrap();assert!(document.objects.as_ref().unwrap().meshes.is_empty());assert_eq!(document.objects.as_ref().unwrap().instances.len(),2);assert_eq!(document.definitions.as_ref().unwrap().meshes,[original.clone()]);let mut restored=Scene::empty();scene_document::open(&mut restored,&crate::scene_archive::save(&scene).unwrap()).unwrap();assert_eq!(restored.objects().len(),2);assert!(Rc::ptr_eq(&restored.objects()[0].mesh,&restored.objects()[1].mesh));assert_eq!(restored.objects()[0].model.m,a.model.m);assert_eq!(restored.objects()[1].model.m,b.model.m);assert_eq!(restored.objects()[0].geometry().unwrap().to_proto(),original);
}
#[test]
fn copied_and_deleted_instance_rows_keep_definitions_and_release_closed_history() {
    let mut scene=Scene::empty();scene_document::import(&mut scene,&instance_specimen::bytes(),"",&Xform::identity(),0.).unwrap();let first=scene.objects()[0].id;let second=scene.objects()[1].id;let source=Rc::downgrade(scene.objects()[0].geometry().unwrap());let document=Rc::downgrade(&scene.instances[&first].document);let copy=scene.copy_row(first,false).unwrap();scene.translate(copy,[0.25,0.,0.]).unwrap();assert!(Rc::ptr_eq(scene.objects()[0].geometry().unwrap(),scene.objects()[2].geometry().unwrap()));assert!(scene.remove(second));let saved=Bundle::decode(&crate::scene_archive::save(&scene).unwrap()).unwrap();let refs=saved.documents.iter().map(|raw|proto::Session::decode(raw.as_slice()).unwrap().objects.unwrap().instances.len()).sum::<usize>();assert_eq!(refs,2);let bytes=crate::scene_archive::save(&scene).unwrap();let mut restored=Scene::empty();scene_document::open(&mut restored,&bytes).unwrap();assert_eq!(restored.objects().len(),2);assert!(restored.objects().iter().all(|row|restored.instances.contains_key(&row.id)));scene.clear();assert!(document.upgrade().is_none());assert!(source.upgrade().is_none());
}
#[test]
fn invalid_definition_references_and_part_edits_leave_existing_sources_unchanged() {
    let mut scene=Scene::demo();let before=scene.objects()[0].id;let mut invalid=instance_specimen::message();invalid.objects.as_mut().unwrap().instances[0].definition_guid="missing".into();assert!(scene_document::import(&mut scene,&invalid.encode_to_vec(),"",&Xform::identity(),0.).is_err());assert_eq!(scene.objects()[0].id,before);
    scene.clear();scene_document::import(&mut scene,&instance_specimen::bytes(),"",&Xform::identity(),0.).unwrap();let owner=scene.objects()[0].id;let target=crate::pick_sources::Target {owner,part:crate::pick_sources::Part::Face(0)};let original=scene.objects()[0].geometry().unwrap().to_proto();assert!(crate::part_preview::Preview::new(&scene,target).is_err());assert_eq!(scene.objects()[0].geometry().unwrap().to_proto(),original);
}

#[test]
fn shared_instance_snapshots_count_original_owners_once_and_conflicting_definitions_cannot_merge() {
    let mut scene=Scene::empty();scene_document::import(&mut scene,&instance_specimen::bytes(),"first",&Xform::identity(),0.).unwrap();let snapshot=scene.clone();assert_eq!(crate::memory::instances([&scene,&snapshot]),[4,1,1]);let mut other=instance_specimen::message();let guid=scene.instances.values().next().unwrap().definition.guid().to_owned();other.definitions.as_mut().unwrap().meshes[0].guid=guid.clone();other.definitions.as_mut().unwrap().meshes[0].name="Different original".into();for instance in &mut other.objects.as_mut().unwrap().instances {instance.definition_guid=guid.clone();}
    scene_document::import(&mut scene,&other.encode_to_vec(),"second",&Xform::identity(),0.).unwrap();assert_eq!(crate::memory::instances([&scene]),[4,2,2]);assert!(crate::scene_archive::save(&scene).is_ok());let second=scene.objects()[2].id;let first=scene.forest.documents[0].clone();let key=format!("{}/{}",first.key,first.nodes[0].source.guid);crate::layer_edit::apply(&mut scene,&key,crate::layer_edit::Edit::Move(vec![second])).unwrap();assert!(crate::scene_archive::save(&scene).unwrap_err().contains("Different originals"));scene.clear();assert_eq!(crate::memory::instances([&scene]),[0,0,0]);
}

#[test]
fn instance_colour_overrides_one_placement_without_mutating_definition_and_history_is_reversible() {
    use crate::editor::{Action,Editor};
    let mut original=proto::Session::decode(instance_specimen::display_bytes().as_slice()).unwrap();let definition=original.definitions.as_ref().unwrap().meshes[0].clone();
    let first=&mut original.objects.as_mut().unwrap().instances[0];first.flags|=session_rust::InstanceRef::FLAG_COLOR;first.color=Some(proto::Color {r:0.23,g:0.75,b:0.11,a:0.5,..Default::default()});
    let mut editor=Editor::default();editor.apply(Action::Close).unwrap();let mut ready=Scene::empty();scene_document::import(&mut ready,&original.encode_to_vec(),"",&Xform::identity(),0.).unwrap();editor.apply(Action::Adopt {scene:Box::new(ready),replace:false}).unwrap();let id=editor.scene.objects()[0].id;assert_eq!(editor.scene.face_rgba(id),Some([0.23,0.75,0.11,0.5]));assert_eq!(editor.scene.face_rgba(editor.scene.objects()[1].id),None);assert_eq!(editor.scene.objects()[0].geometry().unwrap().to_proto(),definition);
    editor.apply(Action::Picked(Some(id))).unwrap();editor.apply(Action::Delete).unwrap();assert_eq!(editor.scene.instances.len(),1);editor.apply(Action::Undo).unwrap();assert!(editor.scene.instances.contains_key(&id));editor.apply(Action::Redo).unwrap();assert!(!editor.scene.instances.contains_key(&id));editor.apply(Action::Undo).unwrap();let bytes=crate::scene_archive::save(&editor.scene).unwrap();let mut restored=Scene::empty();scene_document::open(&mut restored,&bytes).unwrap();assert_eq!(restored.face_rgba(restored.objects()[0].id),Some([0.23,0.75,0.11,0.5]));editor.apply(Action::Close).unwrap();assert_eq!(crate::memory::instances(editor.scenes()),[0,0,0]);
}

#[test]
fn every_basic_definition_family_roundtrips_as_original_references() {
    use crate::editor::{Editor,Action};
    let mut editor=Editor::default();editor.apply(Action::Close).unwrap();for action in [Action::AddBox,Action::AddCad,Action::AddSurface,Action::AddCurve,Action::AddPolyline,Action::AddLine,Action::AddPoint,Action::AddCloud] {editor.apply(action).unwrap();}
    let mut definitions=crate::geometry_snapshot::objects(&editor.scene,&editor.scene.all_ids()).unwrap();definitions.instances.clear();let mut refs=Vec::new();let mut index=0;
    macro_rules! reference {($field:ident)=>{for definition in &definitions.$field {for n in 0..2 {refs.push(proto::InstanceRef {guid:format!("original-{index}-{n}"),name:format!("Placement {index}-{n}"),definition_guid:definition.guid.clone(),..Default::default()});}index+=1;}};}
    reference!(meshes);reference!(breps);reference!(nurbssurfaces);reference!(nurbscurves);reference!(polylines);reference!(lines);reference!(points);reference!(pointclouds);assert_eq!(index,8);
    let original=proto::Session {objects:Some(proto::Objects {instances:refs,..Default::default()}),definitions:Some(definitions.clone()),..Default::default()};let mut scene=Scene::empty();scene_document::import(&mut scene,&original.encode_to_vec(),"",&Xform::identity(),0.).unwrap();assert_eq!(scene.instances.len(),16);let bytes=crate::scene_archive::save(&scene).unwrap();let bundle=Bundle::decode(&bytes).unwrap();let saved=proto::Session::decode(bundle.documents[0].as_slice()).unwrap();assert_eq!(saved.objects.unwrap().instances.len(),16);let saved_defs=saved.definitions.unwrap();macro_rules! equal {($field:ident)=>{assert_eq!(saved_defs.$field,definitions.$field);};}equal!(meshes);equal!(breps);equal!(nurbssurfaces);equal!(nurbscurves);equal!(polylines);equal!(lines);equal!(points);equal!(pointclouds);let mut restored=Scene::empty();scene_document::open(&mut restored,&bytes).unwrap();assert_eq!(restored.instances.len(),16);assert_eq!(crate::memory::instances([&restored]),[16,1,8]);
}
